import { FormEvent, useEffect, useState } from 'react'
import { api, date, number } from '../api'
import { Pipeline, User, Version } from '../types'
import Layout, { Empty, Modal, navigate, Spinner, Status } from '../components/Layout'
import { errorMessage } from '../App'

type Props={path:string;user:User;version:Version;approvalEnabled:boolean;onLogout:()=>void;notify:(m:string,e?:boolean)=>void}
export default function AdminPages(props:Props){const canAdmin=props.user.isBootstrap||props.user.permissions.includes('admin:*')||props.user.permissions.includes('admin:read');if(!canAdmin)return <Layout area="admin" {...props} title="접근 권한 없음"><div className="panel"><Empty title="관리자 권한이 필요합니다" description="CRM 관리자에게 admin:read 권한을 요청하세요."/></div></Layout>;switch(props.path){case'/admin/operations':return <Operations {...props}/>;case'/admin/system':return <SystemSettings {...props}/>;case'/admin/oidc':return <OIDC {...props}/>;case'/admin/users':return <Users {...props}/>;case'/admin/roles':return <Roles {...props}/>;case'/admin/pipeline':return <AdminPipeline {...props}/>;case'/admin/sales-execution':return <SalesExecution {...props}/>;case'/admin/relationships':return <RelationshipIntelligenceSettings {...props}/>;case'/admin/approval':return <ApprovalPolicies {...props}/>;case'/admin/keys':return <KeyPolicies {...props}/>;case'/admin/custom-fields':return <CustomFields {...props}/>;case'/admin/security':return <Security {...props}/>;case'/admin/audit':return <Audit {...props}/>;case'/admin/data':return <DataManagement {...props}/>;default:return <Overview {...props}/>}}
function Frame({children,title,subtitle,actions,...props}:Props&{children:React.ReactNode;title:string;subtitle?:string;actions?:React.ReactNode}){return <Layout area="admin" {...props} title={title} subtitle={subtitle} actions={actions}>{children}</Layout>}

type Diagnostic={key:string;label:string;status:string;summary:string;route?:string;required:boolean}
type ActionItem={severity:string;title:string;description:string;route?:string}
type OperationsData={application:any;database:any;jobs:{ready:number;running:number;failed:number};counts:Record<string,number>;features:Record<string,boolean>;diagnostics:Diagnostic[];actions:ActionItem[];recentJobs:any[];readinessScore:number;uptimeSeconds:number;generatedAt:string}

function useOperations(notify:Props['notify']){
  const [data,setData]=useState<OperationsData|null>(null);const [loading,setLoading]=useState(true)
  const load=async()=>{setLoading(true);try{setData(await api<OperationsData>('/api/v1/admin/operations'))}catch(e){notify(errorMessage(e),true)}finally{setLoading(false)}}
  useEffect(()=>{void load()},[])
  return {data,loading,load}
}
const diagnosticIcon=(status:string)=>status==='HEALTHY'?'✓':status==='DISABLED'?'–':'!'
const uptime=(seconds:number)=>seconds>=86400?`${Math.floor(seconds/86400)}일 ${Math.floor(seconds%86400/3600)}시간`:seconds>=3600?`${Math.floor(seconds/3600)}시간 ${Math.floor(seconds%3600/60)}분`:`${Math.max(1,Math.floor(seconds/60))}분`

function Overview(props:Props){
  const {data,loading,load}=useOperations(props.notify)
  const actions=<><button className="btn btn-secondary" disabled={loading} onClick={()=>void load()}>{loading?'확인 중…':'↻ 새로고침'}</button><a className="btn btn-primary" href="/api/v1/admin/operations/support-bundle" download>Support Bundle</a></>
  return <Frame {...props} title="운영 Command Center" subtitle="서비스 준비도와 조치 대상을 한 화면에서 판단합니다." actions={actions}>{!data?<Spinner/>:<>
    <section className="command-hero panel"><div className="readiness-ring" style={{background:`conic-gradient(#20a69e ${data.readinessScore}%, #dfe8ed 0)`}}><div><strong>{data.readinessScore}</strong><small>/ 100</small></div></div><div className="command-copy"><p className="eyebrow">OPERATIONAL READINESS</p><h2>{data.readinessScore===100?'필수 운영 항목이 모두 준비됐습니다':`${data.actions.filter(x=>x.severity!=='INFO').length}개 항목을 확인하세요`}</h2><p>필수 진단 {data.diagnostics.filter(x=>x.required&&x.status==='HEALTHY').length}/{data.diagnostics.filter(x=>x.required).length} 정상 · 마지막 확인 {date(data.generatedAt)}</p><div className="feature-chips">{Object.entries(data.features).map(([key,on])=><span className={on?'on':'off'} key={key}><i/>{key.toUpperCase()} {on?'ON':'OFF'}</span>)}</div></div><div className="command-build"><small>RUNNING VERSION</small><b>Relio v{data.application.version}</b><code>{data.application.gitCommit}</code><span>Uptime {uptime(data.uptimeSeconds)}</span></div></section>
    <div className="admin-metric-grid"><article><span>활성 사용자</span><strong>{number(data.counts.activeUsers)}</strong><small>전체 {number(data.counts.users)}명</small></article><article><span>활성 Personal Key</span><strong>{number(data.counts.activeKeys)}</strong><small>REST · MCP</small></article><article><span>최근 24시간 Audit</span><strong>{number(data.counts.audit24h)}</strong><small>전체 Channel</small></article><article><span>진행 Opportunity</span><strong>{number(data.counts.openOpportunities)}</strong><small>고객 {number(data.counts.customers)}개</small></article></div>
    <div className="command-grid"><section className="panel action-center"><div className="panel-head"><div><h2>Action Center</h2><p>우선순위가 높은 운영 조치입니다.</p></div><span className="count-badge">{data.actions.length}</span></div><div className="action-list">{data.actions.slice(0,5).map((item,i)=><button key={i} onClick={()=>item.route&&navigate(item.route)} disabled={!item.route}><span className={`action-severity ${item.severity.toLowerCase()}`}>{item.severity==='CRITICAL'?'긴급':item.severity==='WARNING'?'확인':'완료'}</span><span><b>{item.title}</b><small>{item.description}</small></span>{item.route&&<em>→</em>}</button>)}</div></section>
    <section className="panel diagnostic-preview"><div className="panel-head"><div><h2>System Diagnostics</h2><p>핵심 서비스와 보안 구성 상태</p></div><button onClick={()=>navigate('/admin/operations')}>전체 보기 →</button></div><div>{data.diagnostics.slice(0,8).map(item=><button key={item.key} onClick={()=>item.route&&navigate(item.route)} disabled={!item.route}><span className={`diagnostic-dot ${item.status.toLowerCase()}`}>{diagnosticIcon(item.status)}</span><span><b>{item.label}</b><small>{item.summary}</small></span><Status value={item.status}/></button>)}</div></section></div>
    <section className="quick-admin panel"><div className="panel-head"><div><h2>빠른 관리</h2><p>자주 사용하는 관리 작업으로 바로 이동합니다.</p></div></div><div>{[['/admin/users','사용자 초대 · 조직','조직 구조와 Role을 관리합니다.'],['/admin/oidc','SSO 연결 점검','Keycloak Discovery와 Claim을 검사합니다.'],['/admin/pipeline','Pipeline 편집','Stage와 성공확률을 조정합니다.'],['/admin/keys','API · MCP 정책','키 수명, Scope와 Tool을 통제합니다.']].map(([route,title,copy])=><button key={route} onClick={()=>navigate(route)}><b>{title}</b><small>{copy}</small><span>→</span></button>)}</div></section>
  </>}</Frame>
}

function Operations(props:Props){
  const {data,loading,load}=useOperations(props.notify)
  return <Frame {...props} title="Diagnostics · Job" subtitle="런타임, 데이터베이스, 보안 구성과 Background Job을 점검합니다." actions={<><button className="btn btn-secondary" disabled={loading} onClick={()=>void load()}>{loading?'진단 중…':'↻ 진단 다시 실행'}</button><a className="btn btn-primary" href="/api/v1/admin/operations/support-bundle" download>Support Bundle</a></>}>{!data?<Spinner/>:<>
    <div className="diagnostic-grid">{data.diagnostics.map(item=><article className={`diagnostic-card ${item.status.toLowerCase()}`} key={item.key}><span className="diagnostic-card-icon">{diagnosticIcon(item.status)}</span><div><div><h3>{item.label}</h3><Status value={item.status}/></div><p>{item.summary}</p>{item.required&&<small>필수 운영 항목</small>}</div>{item.route&&<button aria-label={`${item.label} 설정으로 이동`} onClick={()=>navigate(item.route!)}>→</button>}</article>)}</div>
    <div className="operations-grid"><section className="panel"><div className="panel-head"><div><h2>Application · Database</h2><p>Image Metadata와 Migration 상태</p></div><Status value={data.database.migration.status}/></div><div className="info-list"><div><span>Application Version</span><b>{data.application.version}</b></div><div><span>Git Commit</span><code>{data.application.gitCommit}</code></div><div><span>Build Date</span><b>{data.application.buildDate}</b></div><div><span>Schema Version</span><b>{data.database.migration.schemaVersion}</b></div><div><span>Last Migration</span><b>{date(data.database.migration.lastMigration)}</b></div><div><span>Database Size</span><b>{formatBytes(data.database.sizeBytes)}</b></div><div><span>PostgreSQL</span><small className="truncate">{data.database.serverVersion}</small></div></div></section><section className="panel"><div className="panel-head"><div><h2>Offline Runtime Contract</h2><p>운영 시 외부 다운로드 없는 단일 Image 구성</p></div><Status value="VERIFIED"/></div><div className="runtime-contract"><div><span>3</span><p><b>환경변수</b><small>POSTGRES_DSN · BOOTSTRAP_ADMIN · BOOTSTRAP_ADMIN_PASSWORD</small></p></div><div><span>1</span><p><b>Docker Image</b><small>Go Binary · React Assets · Migration · OpenAPI · MCP</small></p></div><div><span>0</span><p><b>Runtime Download</b><small>CDN · Font · Telemetry · License Check 없음</small></p></div></div><div className="support-note"><b>Support Bundle은 안전합니다</b><p>Password, Token, Personal Key, PostgreSQL DSN, OIDC Client Secret은 포함하지 않으며 다운로드 이력은 Audit에 기록됩니다.</p></div></section></div>
    <section className="panel table-panel job-panel"><div className="panel-head"><div><h2>Background Job</h2><p>최근 실행 예정 및 실패 작업입니다.</p></div><div className="job-summary"><Status value={`${data.jobs.ready} READY`}/><Status value={`${data.jobs.running} RUNNING`}/><Status value={`${data.jobs.failed} FAILED`}/></div></div>{data.recentJobs.length?<table><thead><tr><th>Job</th><th>상태</th><th>시도</th><th>실행 예정</th><th>최근 오류</th></tr></thead><tbody>{data.recentJobs.map(job=><tr key={job.id}><td><b>{job.type}</b><code className="table-sub">{job.id}</code></td><td><Status value={job.status}/></td><td>{job.attempts} / {job.maxAttempts}</td><td>{date(job.runAt)}</td><td><span className="truncate">{job.lastError||'—'}</span></td></tr>)}</tbody></table>:<Empty icon="✓" title="등록된 Background Job이 없습니다" description="대기·실행·실패 작업이 생기면 이곳에서 상태와 오류를 확인할 수 있습니다."/>}</section>
  </>}</Frame>
}

type Setting={namespace:string;key:string;value:any;valueType:string;secret:boolean;configured:boolean;restartRequired:boolean;version:number}
function useSettings(namespace?:string){const [items,setItems]=useState<Setting[]|null>(null);const load=()=>api<{items:Setting[]}>(`/api/v1/admin/settings${namespace?'?namespace='+namespace:''}`).then(v=>setItems(v.items));useEffect(()=>{load().catch(()=>setItems([]))},[namespace]);return {items,load}}
async function saveSetting(item:Partial<Setting>&{namespace:string;key:string;value:any}){return api(`/api/v1/admin/settings/${item.namespace}/${item.key}`,{method:'PUT',body:JSON.stringify({value:item.value,valueType:item.valueType||typeof item.value,secret:item.secret||false,restartRequired:item.restartRequired||false,version:item.version||0})})}
function SystemSettings(props:Props){
  const {items,load}=useSettings();const [dirty,setDirty]=useState(false);const [busy,setBusy]=useState(false);const [savedAt,setSavedAt]=useState<string>()
  const get=(ns:string,key:string,fallback:any)=>items?.find(x=>x.namespace===ns&&x.key===key)?.value??fallback
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);try{await Promise.all([saveSetting({namespace:'system',key:'service_name',value:f.get('name'),valueType:'string'}),saveSetting({namespace:'system',key:'service_url',value:f.get('url'),valueType:'string'}),saveSetting({namespace:'system',key:'locale',value:f.get('locale'),valueType:'string'}),saveSetting({namespace:'system',key:'timezone',value:f.get('timezone'),valueType:'string'})]);props.notify('시스템 설정을 저장했습니다.');setDirty(false);setSavedAt(new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'}));await load()}catch(e){props.notify(errorMessage(e),true)}finally{setBusy(false)}}
  return <Frame {...props} title="시스템 기본정보" subtitle="환경변수 변경 없이 서비스 이름, URL과 지역 설정을 관리합니다.">{!items?<Spinner/>:<form className="settings-stack" onSubmit={submit} onChange={()=>setDirty(true)}><section className="panel settings-section"><div className="settings-title"><span>R</span><div><h2>서비스 기본정보</h2><p>로그인 화면, OIDC Callback과 서비스 전반에 적용됩니다.</p></div></div><div className="form-grid"><label>서비스명<input name="name" required defaultValue={get('system','service_name','Relio')}/></label><label>Service URL<input name="url" type="url" required defaultValue={get('system','service_url','http://localhost:8080')}/><small>운영 사용자가 접근하는 URL이며 OIDC Callback의 기준입니다.</small></label><label>Locale<select name="locale" defaultValue={get('system','locale','ko-KR')}><option>ko-KR</option><option>en-US</option></select></label><label>Timezone<select name="timezone" defaultValue={get('system','timezone','Asia/Seoul')}><option>Asia/Seoul</option><option>UTC</option><option>Asia/Tokyo</option></select></label></div></section><section className="panel settings-section"><div className="settings-title"><span>↻</span><div><h2>설정 적용 방식</h2><p>Dynamic 설정은 저장 즉시 모든 인스턴스에 적용됩니다.</p></div></div><div className="setting-badges"><div><Status value="DYNAMIC"/><b>즉시 적용</b><p>Pipeline, 권한, 승인, API/MCP, 개인키 정책</p></div><div><Status value="RESTART_REQUIRED"/><b>재시작 필요</b><p>필요한 설정은 저장 후 관리자 화면에 명확히 표시됩니다.</p></div></div></section><div className={`sticky-save ${dirty?'dirty':''}`}><span>{busy?'설정을 안전하게 저장하는 중입니다…':dirty?'저장되지 않은 변경 사항이 있습니다.':savedAt?`${savedAt} 저장 완료 · 모든 변경은 Audit에 기록됩니다.`:'변경 사항은 모두 Audit에 기록됩니다.'}</span><button className="btn btn-primary" disabled={busy||!dirty}>{busy?'저장 중…':'설정 저장'}</button></div></form>}</Frame>}

function RelationshipIntelligenceSettings(props:Props){
  const {items,load}=useSettings('relationship_intelligence')
  const get=(key:string,fallback:any)=>items?.find(x=>x.key===key)?.value??fallback
  const roles=['PRESALES','CONSULTANT','MANAGER','EXECUTIVE_SPONSOR','LEGAL','DELIVERY','OTHER']
  async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);try{await Promise.all([saveSetting({namespace:'relationship_intelligence',key:'graph_max_nodes',value:Number(f.get('graphMax'))}),saveSetting({namespace:'relationship_intelligence',key:'default_plan_year',value:Number(f.get('planYear'))}),saveSetting({namespace:'relationship_intelligence',key:'allowed_opportunity_roles',value:f.getAll('roles'),valueType:'json'})]);props.notify('Relationship Intelligence 정책을 저장했습니다.');load()}catch(e){props.notify(errorMessage(e),true)}}
  return <Frame {...props} title="Relationship Intelligence" subtitle="고객 관계망, 전략 Account Plan과 Opportunity Team 정책을 중앙 관리합니다.">{!items?<Spinner/>:<form className="settings-stack" onSubmit={submit}><section className="panel settings-section"><div className="settings-title"><span>◎</span><div><h2>Relationship Graph</h2><p>Customer 360에서 한 번에 분석하고 표시할 담당자 수를 제한합니다.</p></div></div><div className="form-grid"><label>최대 Graph Node<input name="graphMax" type="number" min="10" max="200" defaultValue={get('graph_max_nodes',100)}/><small>10~200명, 저장 즉시 적용</small></label><label>기본 Account Plan 연도<input name="planYear" type="number" min="0" max="2200" defaultValue={get('default_plan_year',0)}/><small>0이면 현재 연도를 자동 사용합니다.</small></label></div></section><section className="panel settings-section"><div className="settings-title"><span>◇</span><div><h2>Opportunity Team Role</h2><p>영업건에 추가할 수 있는 협업 역할을 허용 목록으로 관리합니다.</p></div></div><div className="role-policy-grid">{roles.map(role=><label className="check-label" key={role}><input name="roles" type="checkbox" value={role} defaultChecked={(get('allowed_opportunity_roles',roles) as string[]).includes(role)}/><span><b>{role}</b><small>{({PRESALES:'기술영업',CONSULTANT:'컨설팅',MANAGER:'팀장 검토',EXECUTIVE_SPONSOR:'임원 지원',LEGAL:'법무',DELIVERY:'구축·이행',OTHER:'기타 협업'} as Record<string,string>)[role]}</small></span></label>)}</div><div className="scope-note">구성원 등록은 협업 역할만 표현하며 기존 USER / TEAM / DEPARTMENT / DIVISION / COMPANY Data Scope를 변경하지 않습니다.</div></section><div className="sticky-save"><span>정책 변경은 즉시 적용되고 Audit에 기록됩니다.</span><button className="btn btn-primary">정책 저장</button></div></form>}</Frame>
}

function OIDC(props:Props){const [cfg,setCfg]=useState<any>(null);const [test,setTest]=useState<any>(null);const load=()=>api('/api/v1/admin/oidc').then(setCfg).catch(e=>props.notify(errorMessage(e),true));useEffect(()=>{void load()},[]);async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const body={enabled:f.get('enabled')==='on',issuerUrl:f.get('issuer'),clientId:f.get('clientId'),clientSecret:f.get('secret'),scopes:String(f.get('scopes')).split(/\s+/),usernameClaim:f.get('usernameClaim'),emailClaim:f.get('emailClaim'),nameClaim:f.get('nameClaim'),groupClaim:f.get('groupClaim'),roleClaim:f.get('roleClaim'),autoProvision:f.get('auto')==='on',defaultRoleId:f.get('defaultRole'),rootCaPem:f.get('rootCa')};try{const v=await api<any>('/api/v1/admin/oidc',{method:'PUT',body:JSON.stringify(body)});setCfg(v);props.notify('Keycloak OIDC 설정을 저장했습니다.')}catch(e){props.notify(errorMessage(e),true)}}async function testConnection(){try{const v=await api<any>('/api/v1/admin/oidc/test',{method:'POST'});setTest(v);props.notify(v.success?'OIDC 연결 테스트가 완료되었습니다.':'일부 연결 검사가 실패했습니다.',!v.success)}catch(e){props.notify(errorMessage(e),true)}}if(!cfg)return <Frame {...props} title="Keycloak OIDC"><Spinner/></Frame>;return <Frame {...props} title="Keycloak OIDC" subtitle="Issuer, Client ID, Client Secret만으로 사내 SSO를 연결합니다." actions={<div className="toggle-summary"><span className={cfg.enabled?'on':''}/>{cfg.enabled?'SSO 활성':'SSO 비활성'}</div>}><form className="settings-stack" onSubmit={save}><section className="panel settings-section"><div className="settings-title"><span>◎</span><div><h2>연결 설정</h2><p>Issuer Discovery로 Endpoint와 JWKS를 자동 구성합니다.</p></div><label className="switch"><input type="checkbox" name="enabled" defaultChecked={cfg.enabled}/><span/>SSO 활성화</label></div><div className="form-grid"><label className="span-2">Issuer URL *<input name="issuer" required defaultValue={cfg.issuerUrl} placeholder="https://keycloak.example/realms/company"/></label><label>Client ID *<input name="clientId" required defaultValue={cfg.clientId} placeholder="relio"/></label><label>Client Secret *<input name="secret" type="password" placeholder={cfg.clientSecretConfigured?'설정됨 — 변경할 때만 입력':'Confidential Client Secret'}/></label><label className="span-2">Scope<input name="scopes" defaultValue={(cfg.scopes||['openid','profile','email']).join(' ')}/></label><label className="span-2">Callback URL<input readOnly value={cfg.callbackUrl}/><small>이 URL을 Keycloak Valid Redirect URIs에 등록하세요.</small></label></div></section><section className="panel settings-section"><div className="settings-title"><span>⌘</span><div><h2>Claim Mapping</h2><p>Keycloak 토큰 Claim을 Relio 사용자 정보에 연결합니다.</p></div></div><div className="form-grid"><label>Username Claim<input name="usernameClaim" defaultValue={cfg.usernameClaim}/></label><label>Email Claim<input name="emailClaim" defaultValue={cfg.emailClaim}/></label><label>Name Claim<input name="nameClaim" defaultValue={cfg.nameClaim}/></label><label>Group Claim<input name="groupClaim" defaultValue={cfg.groupClaim}/></label><label>Role Claim<input name="roleClaim" defaultValue={cfg.roleClaim}/></label><label>Default Role ID<input name="defaultRole" defaultValue={cfg.defaultRoleId}/></label><label className="check-label span-2"><input type="checkbox" name="auto" defaultChecked={cfg.autoProvision}/> 첫 로그인 시 사용자 자동 생성</label></div></section><section className="panel settings-section"><div className="settings-title"><span>⌁</span><div><h2>사내 Root CA</h2><p>폐쇄망 Keycloak이 사설 인증서를 사용할 때만 등록합니다.</p></div></div><label>PEM Certificate<textarea name="rootCa" rows={5} defaultValue={cfg.rootCaPem} placeholder="-----BEGIN CERTIFICATE-----"/></label></section><OIDCClaimMappings providerReady={Boolean(cfg.id)} notify={props.notify}/>{test&&<section className="panel test-result"><div className="panel-head"><h2>연결 테스트 결과</h2><Status value={test.success?'SUCCESS':'FAILED'}/></div><div className="check-list">{Object.entries(test.checks).map(([k,v])=><div key={k}><span className={String(v).startsWith('failed')?'fail':String(v).startsWith('warning')?'warn':'ok'}>{String(v).startsWith('failed')?'×':String(v).startsWith('warning')?'!':'✓'}</span><b>{k}</b><small>{String(v)}</small></div>)}</div></section>}<div className="sticky-save"><button type="button" className="btn btn-secondary" onClick={testConnection} disabled={!cfg.id}>연결 테스트</button><span>Secret은 Application Encryption으로 저장됩니다.</span><button className="btn btn-primary">OIDC 설정 저장</button></div></form></Frame>}

function OIDCClaimMappings({providerReady,notify}:{providerReady:boolean;notify:Props['notify']}){
  const [roles,setRoles]=useState<any[]>([]),[orgs,setOrgs]=useState<any[]>([]),[mappings,setMappings]=useState<{roles:any[];groups:any[]}>({roles:[],groups:[]})
  useEffect(()=>{if(!providerReady)return;Promise.all([api<{items:any[]}>('/api/v1/admin/roles'),api<{items:any[]}>('/api/v1/admin/organizations'),api<{roles:any[];groups:any[]}>('/api/v1/admin/oidc/mappings')]).then(([r,o,m])=>{setRoles(r.items);setOrgs(o.items);setMappings(m)}).catch(e=>notify(errorMessage(e),true))},[providerReady])
  const updateRole=(i:number,k:string,v:string)=>setMappings(m=>({...m,roles:m.roles.map((x,n)=>n===i?{...x,[k]:v}:x)}))
  const updateGroup=(i:number,k:string,v:string)=>setMappings(m=>({...m,groups:m.groups.map((x,n)=>n===i?{...x,[k]:v}:x)}))
  async function save(){try{const v=await api<{roles:any[];groups:any[]}>('/api/v1/admin/oidc/mappings',{method:'PUT',body:JSON.stringify(mappings)});setMappings(v);notify('Role · Group Claim 매핑을 저장했습니다.')}catch(e){notify(errorMessage(e),true)}}
  return <section className="panel settings-section"><div className="settings-title"><span>↔</span><div><h2>Role · Group Mapping</h2><p>외부 Role은 Relio Role로, Group은 조직으로 자동 매핑합니다.</p></div></div>{!providerReady?<div className="alert"><b>먼저 OIDC 설정을 저장하세요</b><span>Provider가 생성된 후 Claim 매핑을 구성할 수 있습니다.</span></div>:<><div className="mapping-grid"><div><div className="panel-head"><h2>Role Mapping</h2><button type="button" onClick={()=>setMappings(m=>({...m,roles:[...m.roles,{externalRole:'',roleId:roles[0]?.id||''}]}))}>＋ 추가</button></div>{mappings.roles.map((x,i)=><div className="mapping-row" key={i}><input value={x.externalRole} onChange={e=>updateRole(i,'externalRole',e.target.value)} placeholder="keycloak-role"/><span>→</span><select value={x.roleId} onChange={e=>updateRole(i,'roleId',e.target.value)}>{roles.map(r=><option key={r.id} value={r.id}>{r.name} · {r.dataScope}</option>)}</select><button type="button" onClick={()=>setMappings(m=>({...m,roles:m.roles.filter((_,n)=>n!==i)}))}>×</button></div>)}</div><div><div className="panel-head"><h2>Group → 조직</h2><button type="button" onClick={()=>setMappings(m=>({...m,groups:[...m.groups,{externalGroup:'',organizationId:orgs[0]?.id||''}]}))}>＋ 추가</button></div>{mappings.groups.map((x,i)=><div className="mapping-row" key={i}><input value={x.externalGroup} onChange={e=>updateGroup(i,'externalGroup',e.target.value)} placeholder="/sales/team-a"/><span>→</span><select value={x.organizationId} onChange={e=>updateGroup(i,'organizationId',e.target.value)}>{orgs.map(o=><option key={o.id} value={o.id}>{o.name} · {o.code}</option>)}</select><button type="button" onClick={()=>setMappings(m=>({...m,groups:m.groups.filter((_,n)=>n!==i)}))}>×</button></div>)}</div></div><button type="button" className="btn btn-secondary" onClick={save}>Claim 매핑 저장</button></>}</section>
}

function Users(props:Props){const [users,setUsers]=useState<any[]|null>(null);const [orgs,setOrgs]=useState<any[]>([]);const [modal,setModal]=useState(false);const load=()=>Promise.all([api<{items:any[]}>('/api/v1/admin/users'),api<{items:any[]}>('/api/v1/admin/organizations')]).then(([u,o])=>{setUsers(u.items);setOrgs(o.items)}).catch(e=>props.notify(errorMessage(e),true));useEffect(()=>{void load()},[]);return <Frame {...props} title="사용자 · 조직" subtitle="로컬 및 OIDC 사용자를 조직 구조와 연결합니다." actions={<button className="btn btn-primary" onClick={()=>setModal(true)}>＋ 사용자 생성</button>}>{!users?<Spinner/>:<><div className="admin-tabs"><button className="active">사용자 {users.length}</button><button>조직 {orgs.length}</button></div><section className="panel table-panel"><table><thead><tr><th>사용자</th><th>인증</th><th>조직 · 직급</th><th>Role</th><th>최근 로그인</th><th>상태</th></tr></thead><tbody>{users.map(x=><tr key={x.id}><td><div className="entity-cell"><span className="avatar">{x.displayName.slice(0,1)}</span><span><b>{x.displayName}{x.isBootstrap&&<em className="breakglass-tag">BREAK GLASS</em>}</b><small>{x.username} · {x.email||'이메일 없음'}</small></span></div></td><td><Status value={x.authSource}/></td><td>{x.organizationName||'미지정'}<small className="table-sub">{x.title||''}</small></td><td>{x.roles.join(', ')||'없음'}</td><td>{relativeAdmin(x.lastLoginAt)}</td><td><Status value={x.active?'ACTIVE':'DISABLED'}/></td></tr>)}</tbody></table></section></>}{modal&&<UserModal orgs={orgs} onClose={()=>setModal(false)} onSaved={()=>{setModal(false);load()}} notify={props.notify}/>}</Frame>}
function UserModal({orgs,onClose,onSaved,notify}:{orgs:any[];onClose:()=>void;onSaved:()=>void;notify:Props['notify']}){async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/admin/users',{method:'POST',body:JSON.stringify({username:f.get('username'),displayName:f.get('name'),email:f.get('email'),password:f.get('password'),organizationId:f.get('org'),title:f.get('title'),roleIds:[]})});notify('사용자를 생성했습니다. 첫 로그인 시 비밀번호 변경이 필요합니다.');onSaved()}catch(e){notify(errorMessage(e),true)}}return <Modal title="로컬 사용자 생성" onClose={onClose} wide><form className="form" onSubmit={submit}><div className="form-grid"><label>사용자 ID *<input name="username" required autoFocus/></label><label>이름 *<input name="name" required/></label><label>이메일<input name="email" type="email"/></label><label>초기 비밀번호 *<input name="password" type="password" minLength={12} required/></label><label>조직<select name="org"><option value="">미지정</option>{orgs.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></label><label>직급<input name="title"/></label></div><div className="alert"><b>최초 로그인 정책</b><span>사용자는 첫 로그인 직후 비밀번호 변경을 완료해야 CRM에 접근할 수 있습니다.</span></div><div className="modal-actions"><button type="button" className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary">사용자 생성</button></div></form></Modal>}

function Roles(props:Props){const [items,setItems]=useState<any[]|null>(null);useEffect(()=>{api<{items:any[]}>('/api/v1/admin/roles').then(v=>setItems(v.items)).catch(e=>props.notify(errorMessage(e),true))},[]);return <Frame {...props} title="권한 · 데이터 범위" subtitle="기능 권한과 데이터 조회 범위를 분리해 최소 권한을 적용합니다." actions={<button className="btn btn-primary">＋ Role 생성</button>}>{!items?<Spinner/>:<><div className="permission-equation"><span>Effective Permission</span><b>=</b><em>Function Permission</em><b>＋</b><em>Data Scope</em><b>＋</b><em>API Key Scope</em></div><div className="role-grid">{items.map(x=><article className="panel role-card" key={x.id}><header><div><span className="role-icon">{x.systemRole?'★':'♙'}</span><div><h3>{x.name}</h3><code>{x.code}</code></div></div><Status value={x.dataScope}/></header><p>{x.description||'설명 없음'}</p><div className="permission-chips">{x.permissions.slice(0,8).map((p:string)=><span key={p}>{p}</span>)}</div><footer><span>{x.permissions.length} permissions</span><button>상세 보기 →</button></footer></article>)}</div></>}</Frame>}

function AdminPipeline(props:Props){const [items,setItems]=useState<Pipeline[]|null>(null);useEffect(()=>{api<{items:Pipeline[]}>('/api/v1/admin/pipelines').then(v=>setItems(v.items)).catch(e=>props.notify(errorMessage(e),true))},[]);return <Frame {...props} title="CRM · Pipeline" subtitle="영업 Stage와 성공확률을 코드 변경 없이 구성합니다.">{!items?<Spinner/>:items.map(p=><section className="panel settings-section" key={p.id}><div className="panel-head"><div><h2>{p.name}</h2><p>{p.default?'기본 Pipeline':'사용자 지정 Pipeline'}</p></div><Status value={p.active?'ACTIVE':'DISABLED'}/></div><div className="stage-config">{p.stages.map(s=><div key={s.id}><span className="stage-dot large" style={{background:s.color}}/><b>{s.order}. {s.name}</b><span>{s.probability}%</span><Status value={s.forecastCategory}/><small>{s.isWon?'Won Stage':s.isLost?'Lost Stage':s.maxDays?`권장 ${s.maxDays}일`:'진행 Stage'}</small><button>편집</button></div>)}</div></section>)}</Frame>}

function SalesExecution(props:Props){
  const [items,setItems]=useState<any[]|null>(null),[draft,setDraft]=useState<any>(null),[rules,setRules]=useState<any[]|null>(null)
  const {items:settings,load:loadSettings}=useSettings('sales_intelligence')
  const setting=(key:string,fallback:any)=>settings?.find(x=>x.key===key)?.value??fallback
  const choose=(x:any)=>setDraft(JSON.parse(JSON.stringify(x)))
  const load=()=>Promise.all([api<{items:any[]}>('/api/v1/admin/sales-execution'),api<{items:any[]}>('/api/v1/admin/deal-health-rules')]).then(([stages,health])=>{setItems(stages.items);setRules(health.items.map(x=>({...x,thresholdText:JSON.stringify(x.threshold)})));if(!draft&&stages.items.length)choose(stages.items[0])}).catch(e=>props.notify(errorMessage(e),true))
  useEffect(()=>{void load()},[])
  const updateItem=(index:number,key:string,value:any)=>setDraft((d:any)=>({...d,playbook:{...d.playbook,items:d.playbook.items.map((x:any,i:number)=>i===index?{...x,[key]:value}:x)}}))
  const updateCriterion=(index:number,key:string,value:any)=>setDraft((d:any)=>({...d,criteria:d.criteria.map((x:any,i:number)=>i===index?{...x,[key]:value}:x)}))
  async function save(){try{const body={playbookName:draft.playbook.name||`${draft.stageName} Playbook`,guidance:draft.playbook.guidance||'',active:draft.playbook.active!==false,items:draft.playbook.items.map((x:any,i:number)=>({...x,displayOrder:(i+1)*10,itemType:x.itemType||'CHECKLIST'})),criteria:draft.criteria.map((x:any,i:number)=>({...x,displayOrder:(i+1)*10,active:x.active!==false,operator:x.operator||'PRESENT'}))};const v=await api<any>(`/api/v1/admin/stages/${draft.stageId}/sales-execution`,{method:'PUT',body:JSON.stringify(body)});setDraft(v);setItems(old=>old?.map(x=>x.stageId===v.stageId?v:x)||null);props.notify('Stage Playbook과 Exit Criteria를 저장했습니다.')}catch(e){props.notify(errorMessage(e),true)}}
  async function saveRule(index:number){const rule=rules?.[index];if(!rule)return;try{const threshold=JSON.parse(rule.thresholdText||'{}');const v=await api<any>(`/api/v1/admin/deal-health-rules/${rule.id}`,{method:'PUT',body:JSON.stringify({...rule,threshold})});setRules(old=>old?.map((x,i)=>i===index?{...v,thresholdText:JSON.stringify(v.threshold)}:x)||null);props.notify(`${v.name} Rule을 저장했습니다.`)}catch(e){props.notify(errorMessage(e),true)}}
  async function savePolicy(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);try{await Promise.all([saveSetting({namespace:'sales_intelligence',key:'snapshot_enabled',value:f.get('snapshot')==='on'}),saveSetting({namespace:'sales_intelligence',key:'risk_threshold',value:Number(f.get('riskThreshold'))})]);await loadSettings();props.notify('Sales Intelligence 정책을 저장했습니다.')}catch(e){props.notify(errorMessage(e),true)}}
  return <Frame {...props} title="Sales Execution" subtitle="Stage마다 영업 행동과 필수 Exit Criteria를 관리자 정책으로 구성합니다." actions={<button className="btn btn-primary" disabled={!draft} onClick={save}>정책 저장</button>}>
    {!items||!rules||!settings?<Spinner/>:<div className="settings-stack"><form className="panel intelligence-policy" onSubmit={savePolicy}><div className="settings-title"><span>◇</span><div><h2>Sales Intelligence 정책</h2><p>위험 Deal 기준과 Forecast Snapshot 수집을 관리자 설정으로 제어합니다.</p></div></div><div className="form-grid"><label>Manager Review 위험점수<input name="riskThreshold" type="number" min="1" max="100" defaultValue={setting('risk_threshold',40)}/></label><label className="check-label"><input name="snapshot" type="checkbox" defaultChecked={setting('snapshot_enabled',true)}/> 일별 Forecast Snapshot 활성화</label></div><button className="btn btn-secondary">Intelligence 정책 저장</button></form>
    <section className="panel settings-section"><div className="settings-title"><span>!</span><div><h2>Explainable Deal Health Rules</h2><p>점수, 임계값, 권장 행동을 변경하면 Web, API와 MCP 분석에 즉시 반영됩니다.</p></div></div><div className="health-rule-list">{rules.map((x:any,i:number)=><div className="health-rule-admin" key={x.id}><label className="switch"><input type="checkbox" checked={x.active} onChange={e=>setRules(old=>old?.map((r,n)=>n===i?{...r,active:e.target.checked}:r)||null)}/><span/></label><code>{x.code}</code><input value={x.name} onChange={e=>setRules(old=>old?.map((r,n)=>n===i?{...r,name:e.target.value}:r)||null)}/><label>Risk <input type="number" min="0" max="100" value={x.riskScore} onChange={e=>setRules(old=>old?.map((r,n)=>n===i?{...r,riskScore:Number(e.target.value)}:r)||null)}/></label><input value={x.thresholdText} onChange={e=>setRules(old=>old?.map((r,n)=>n===i?{...r,thresholdText:e.target.value}:r)||null)} title="JSON threshold"/><input value={x.recommendedAction} onChange={e=>setRules(old=>old?.map((r,n)=>n===i?{...r,recommendedAction:e.target.value}:r)||null)}/><button className="btn btn-ghost" onClick={()=>saveRule(i)}>저장</button></div>)}</div></section>
    <div className="sales-builder"><aside className="panel stage-selector">{items.map(x=><button className={draft?.stageId===x.stageId?'active':''} key={x.stageId} onClick={()=>choose(x)}><small>{x.pipelineName}</small><b>{x.stageOrder}. {x.stageName}</b><span>{x.playbook.items.length} actions · {x.criteria.length} criteria</span></button>)}</aside>{draft&&<div className="builder-content">
      <section className="panel settings-section"><div className="settings-title"><span>▶</span><div><h2>{draft.stageName} Sales Playbook</h2><p>담당자에게 이 Stage에서 수행할 표준 행동을 안내합니다.</p></div><label className="switch"><input type="checkbox" checked={draft.playbook.active!==false} onChange={e=>setDraft((d:any)=>({...d,playbook:{...d.playbook,active:e.target.checked}}))}/><span/>활성</label></div><div className="form-grid"><label>Playbook 이름<input value={draft.playbook.name||''} onChange={e=>setDraft((d:any)=>({...d,playbook:{...d.playbook,name:e.target.value}}))} placeholder={`${draft.stageName} Playbook`}/></label><label className="span-2">영업 Guidance<textarea rows={3} value={draft.playbook.guidance||''} onChange={e=>setDraft((d:any)=>({...d,playbook:{...d.playbook,guidance:e.target.value}}))} placeholder="이 Stage의 목표와 고객에게 확인해야 할 내용을 설명하세요."/></label></div><div className="builder-list"><div className="builder-list-head"><b>Checklist · Recommended Action</b><button onClick={()=>setDraft((d:any)=>({...d,playbook:{...d.playbook,items:[...d.playbook.items,{title:'',description:'',itemType:'CHECKLIST',fieldKey:'',required:false}]}}))}>＋ 항목</button></div>{draft.playbook.items.map((x:any,i:number)=><div className="builder-row" key={x.id||i}><input value={x.title} onChange={e=>updateItem(i,'title',e.target.value)} placeholder="예: Decision Maker 확인"/><select value={x.itemType} onChange={e=>updateItem(i,'itemType',e.target.value)}><option>CHECKLIST</option><option>ACTION</option><option>FIELD</option></select><input value={x.description||''} onChange={e=>updateItem(i,'description',e.target.value)} placeholder="안내 또는 완료 기준"/><label><input type="checkbox" checked={x.required} onChange={e=>updateItem(i,'required',e.target.checked)}/> 필수</label><button className="danger" onClick={()=>setDraft((d:any)=>({...d,playbook:{...d.playbook,items:d.playbook.items.filter((_:any,n:number)=>n!==i)}}))}>×</button></div>)}</div></section>
      <section className="panel settings-section"><div className="settings-title"><span>⇥</span><div><h2>Stage Exit Criteria</h2><p>OFF는 숨김, WARNING은 안내, BLOCK은 Stage 변경을 차단합니다.</p></div></div><div className="builder-list"><div className="builder-list-head"><b>전환 조건</b><button onClick={()=>setDraft((d:any)=>({...d,criteria:[...d.criteria,{name:'',criterionType:'FIELD_PRESENT',fieldKey:'nextAction',operator:'PRESENT',expectedValue:null,enforcement:'WARNING',message:'',active:true}]}))}>＋ 조건</button></div>{draft.criteria.map((x:any,i:number)=><div className="builder-row criteria" key={x.id||i}><input value={x.name} onChange={e=>updateCriterion(i,'name',e.target.value)} placeholder="조건명"/><select value={x.criterionType} onChange={e=>updateCriterion(i,'criterionType',e.target.value)}><option>FIELD_PRESENT</option><option>DECISION_MAKER</option><option>RECENT_ACTIVITY</option><option>PLAYBOOK_COMPLETE</option><option>CUSTOM_FIELD</option></select><input value={x.fieldKey||''} onChange={e=>updateCriterion(i,'fieldKey',e.target.value)} placeholder="필드 Key"/><select value={x.enforcement} onChange={e=>updateCriterion(i,'enforcement',e.target.value)}><option>WARNING</option><option>BLOCK</option><option>OFF</option></select><input value={x.message||''} onChange={e=>updateCriterion(i,'message',e.target.value)} placeholder="사용자 안내 메시지"/><button className="danger" onClick={()=>setDraft((d:any)=>({...d,criteria:d.criteria.filter((_:any,n:number)=>n!==i)}))}>×</button></div>)}</div></section>
    </div>}</div></div>}
  </Frame>
}

function ApprovalPolicies(props:Props){const [items,setItems]=useState<any[]|null>(null);const [modal,setModal]=useState(false);const load=()=>api<{items:any[]}>('/api/v1/admin/approval-policies').then(v=>setItems(v.items)).catch(e=>props.notify(errorMessage(e),true));useEffect(()=>{void load()},[]);return <Frame {...props} title="승인 Workflow" subtitle="정책이 하나도 없으면 검토·승인·반려 기능은 서비스 전체에서 사라집니다." actions={<button className="btn btn-primary" onClick={()=>setModal(true)}>＋ 승인 정책</button>}>{!items?<Spinner/>:<><div className={`workflow-banner ${items.length?'enabled':'disabled'}`}><span>{items.length?'✓':'○'}</span><div><b>{items.length?'승인 Workflow 활성':'승인 Workflow 비활성'}</b><p>{items.length?`${items.filter(x=>x.active).length}개 활성 정책에 해당하는 업무만 검토 요청을 사용합니다.`:'현재 일반 CRM처럼 모든 업무가 즉시 저장·처리되며 승인 UI와 Status가 없습니다.'}</p></div></div>{items.length?<section className="panel table-panel"><table><thead><tr><th>정책명</th><th>대상</th><th>조건</th><th>승인자</th><th>단계</th><th>상태</th></tr></thead><tbody>{items.map(x=><tr key={x.id}><td><b>{x.name}</b></td><td><Status value={x.entityType}/></td><td><code>{x.conditionField||'ALL'} {x.conditionOperator||''} {String(x.conditionValue??'')}</code></td><td>{x.approverMethod}</td><td>{x.approvalSteps}단계</td><td><Status value={x.active?'ACTIVE':'DISABLED'}/></td></tr>)}</tbody></table></section>:<section className="panel"><Empty icon="✓" title="승인 정책이 없습니다" description="검토요청, 승인, 반려 버튼과 승인 Dashboard는 현재 어디에도 노출되지 않습니다." action={<button className="btn btn-primary" onClick={()=>setModal(true)}>첫 정책 만들기</button>}/></section>}</>}{modal&&<PolicyModal onClose={()=>setModal(false)} onSaved={()=>{setModal(false);load()}} notify={props.notify}/>}</Frame>}
function PolicyModal({onClose,onSaved,notify}:{onClose:()=>void;onSaved:()=>void;notify:Props['notify']}){async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const value=f.get('value');try{await api('/api/v1/admin/approval-policies',{method:'POST',body:JSON.stringify({name:f.get('name'),entityType:f.get('entity'),conditionField:f.get('field'),conditionOperator:f.get('operator'),conditionValue:value?Number(value):null,approverMethod:'MANAGER',approvalSteps:1,allowReject:true,allowResubmit:true,allowDelegate:false,active:true,priority:100})});notify('승인 정책을 활성화했습니다. 해당 업무에 검토 UI가 나타납니다.');onSaved()}catch(e){notify(errorMessage(e),true)}}return <Modal title="팀장 1단계 승인 정책" onClose={onClose} wide><form className="form" onSubmit={submit}><div className="form-grid"><label className="span-2">정책명 *<input name="name" required autoFocus placeholder="예: 5억원 이상 Opportunity"/></label><label>대상 Entity<select name="entity"><option>OPPORTUNITY</option><option>QUOTATION</option><option>CONTRACT</option><option>CUSTOMER</option></select></label><label>조건 Field<select name="field"><option value="expected_amount">expected_amount</option><option value="amount">amount</option><option value="discount_percent">discount_percent</option><option value="status">status</option><option value="">모든 건</option></select></label><label>Operator<select name="operator"><option value="GTE">이상 (GTE)</option><option value="GT">초과 (GT)</option><option value="EQ">같음 (EQ)</option><option value="LTE">이하 (LTE)</option></select></label><label>조건값<input name="value" type="number"/></label><label className="span-2">승인자<input readOnly value="요청자의 팀장 (없으면 시스템 관리자)"/></label></div><div className="modal-actions"><button type="button" className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary">정책 활성화</button></div></form></Modal>}

function KeyPolicies(props:Props){
  const {items,load}=useSettings()
  const g=(ns:string,k:string,f:any)=>items?.find(x=>x.namespace===ns&&x.key===k)?.value??f
  const list=(value:FormDataEntryValue|null)=>String(value||'').split(/[\n,]+/).map(x=>x.trim()).filter(Boolean)
  async function submit(e:FormEvent<HTMLFormElement>){
    e.preventDefault();const f=new FormData(e.currentTarget)
    try{
      await Promise.all([
        saveSetting({namespace:'keys',key:'max_per_user',value:Number(f.get('max'))}),
        saveSetting({namespace:'keys',key:'default_lifetime_days',value:Number(f.get('defaultDays'))}),
        saveSetting({namespace:'keys',key:'max_lifetime_days',value:Number(f.get('maxDays'))}),
        saveSetting({namespace:'keys',key:'rotation_grace_hours',value:Number(f.get('grace'))}),
        saveSetting({namespace:'keys',key:'api_enabled',value:f.get('keyApi')==='on'}),
        saveSetting({namespace:'keys',key:'mcp_enabled',value:f.get('keyMcp')==='on'}),
        saveSetting({namespace:'api',key:'enabled',value:f.get('apiEnabled')==='on'}),
        saveSetting({namespace:'api',key:'rate_limit_per_minute',value:Number(f.get('apiRate'))}),
        saveSetting({namespace:'mcp',key:'enabled',value:f.get('mcpEnabled')==='on'}),
        saveSetting({namespace:'mcp',key:'rate_limit_per_minute',value:Number(f.get('mcpRate'))}),
        saveSetting({namespace:'mcp',key:'allowed_origins',value:list(f.get('origins')),valueType:'json'}),
        saveSetting({namespace:'mcp',key:'tool_allowlist',value:list(f.get('tools')),valueType:'json'}),
      ])
      props.notify('개인키와 API/MCP 정책을 저장했습니다.');load()
    }catch(e){props.notify(errorMessage(e),true)}
  }
  return <Frame {...props} title="개인키 · API · MCP" subtitle="키 수명과 회전, 채널, 요청량, Origin 및 MCP Tool을 중앙 통제합니다.">{!items?<Spinner/>:<form className="settings-stack" onSubmit={submit}>
    <section className="panel settings-section"><div className="settings-title"><span>⌁</span><div><h2>Personal Key 정책</h2><p>관리자는 Secret을 조회할 수 없으며 Metadata와 폐기만 관리합니다.</p></div></div><div className="form-grid">
      <label>사용자별 최대 Key 수<input name="max" type="number" min="1" defaultValue={g('keys','max_per_user',10)}/></label><label>기본 만료일 (일)<input name="defaultDays" type="number" min="1" defaultValue={g('keys','default_lifetime_days',365)}/></label><label>최대 만료일 (일)<input name="maxDays" type="number" min="1" defaultValue={g('keys','max_lifetime_days',730)}/></label><label>Rotation Grace (시간)<input name="grace" type="number" min="0" defaultValue={g('keys','rotation_grace_hours',24)}/></label><label className="check-label"><input name="keyApi" type="checkbox" defaultChecked={g('keys','api_enabled',true)}/> REST Personal Key 발급 허용</label><label className="check-label"><input name="keyMcp" type="checkbox" defaultChecked={g('keys','mcp_enabled',true)}/> MCP Personal Key 발급 허용</label>
    </div></section>
    <section className="panel settings-section"><div className="settings-title"><span>AI</span><div><h2>REST API · MCP 정책</h2><p>정책 변경은 즉시 인증 계층과 MCP Tool 목록에 반영됩니다.</p></div></div><div className="form-grid">
      <label className="check-label"><input name="apiEnabled" type="checkbox" defaultChecked={g('api','enabled',true)}/> Personal Key REST API 활성화</label><label>API 요청 한도 / 분<input name="apiRate" type="number" min="0" defaultValue={g('api','rate_limit_per_minute',120)}/></label><label className="check-label"><input name="mcpEnabled" type="checkbox" defaultChecked={g('mcp','enabled',true)}/> MCP Endpoint 활성화</label><label>MCP 요청 한도 / 분<input name="mcpRate" type="number" min="0" defaultValue={g('mcp','rate_limit_per_minute',60)}/></label><label className="span-2">허용 Origin<textarea name="origins" rows={3} defaultValue={(g('mcp','allowed_origins',[]) as string[]).join('\n')} placeholder="https://agent.internal.example"/><small>비어 있으면 Same-Origin만 허용합니다. 줄바꿈 또는 쉼표로 구분합니다.</small></label><label className="span-2">MCP Tool Allowlist<textarea name="tools" rows={4} defaultValue={(g('mcp','tool_allowlist',[]) as string[]).join('\n')} placeholder="search_customers&#10;get_customer_360"/><small>비어 있으면 권한이 있는 모든 Tool을 허용합니다.</small></label>
    </div><div className="mcp-flow"><span>AI Agent</span><b>→</b><span>Origin · Rate</span><b>→</b><span>Key Scope</span><b>→</b><span>Permission</span><b>→</b><span>Data Scope</span><b>→</b><span>Domain</span></div><p className="endpoint"><code>POST /mcp</code><a href="/api/docs" target="_blank">API 문서 열기 ↗</a></p></section>
    <AdminKeyInventory notify={props.notify}/>
    <div className="sticky-save"><span>모든 정책 변경은 Audit에 기록됩니다.</span><button className="btn btn-primary">정책 저장</button></div>
  </form>}</Frame>
}

function AdminKeyInventory({notify}:{notify:Props['notify']}){
  const [items,setItems]=useState<any[]|null>(null)
  const load=()=>api<{items:any[]}>('/api/v1/admin/personal-keys').then(v=>setItems(v.items)).catch(e=>notify(errorMessage(e),true))
  useEffect(()=>{void load()},[])
  async function revoke(id:string){if(!confirm('이 Personal Key를 즉시 폐기할까요?'))return;try{await api(`/api/v1/admin/personal-keys/${id}`,{method:'DELETE'});notify('Personal Key를 폐기했습니다.');load()}catch(e){notify(errorMessage(e),true)}}
  async function revokeAll(userId:string){if(!confirm('이 사용자의 활성 Key를 모두 폐기할까요?'))return;try{const v=await api<{revoked:number}>(`/api/v1/admin/users/${userId}/keys/revoke-all`,{method:'POST'});notify(`${v.revoked}개 Key를 폐기했습니다.`);load()}catch(e){notify(errorMessage(e),true)}}
  return <section className="panel settings-section"><div className="settings-title"><span>⊘</span><div><h2>Personal Key Metadata</h2><p>관리자는 Raw Secret을 볼 수 없으며 상태 확인과 강제 폐기만 수행합니다.</p></div></div>{!items?<Spinner/>:items.length?<div className="table-panel"><table><thead><tr><th>사용자</th><th>Key</th><th>채널 · Scope</th><th>최근 사용</th><th>상태</th><th/></tr></thead><tbody>{items.map(x=><tr key={x.id}><td><b>{x.displayName}</b><small className="table-sub">{x.username}</small></td><td>{x.name}<code className="key-id">relio_{x.keyId}_••••</code></td><td>{x.channels.join(', ')}<small className="table-sub">{x.scopes.length} scopes</small></td><td>{x.lastUsedAt?relativeAdmin(x.lastUsedAt):'사용 안 함'}<small className="table-sub">{x.lastUsedIp||''}</small></td><td><Status value={x.status}/></td><td><div className="row-menu"><button type="button" className="danger" disabled={x.status==='REVOKED'||x.status==='EXPIRED'} onClick={()=>revoke(x.id)}>폐기</button><button type="button" onClick={()=>revokeAll(x.userId)}>전체 폐기</button></div></td></tr>)}</tbody></table></div>:<Empty title="발급된 Personal Key가 없습니다" description="사용자가 API/MCP Key를 발급하면 Metadata가 표시됩니다."/>}</section>
}

function CustomFields(props:Props){const [items,setItems]=useState<any[]|null>(null);const [modal,setModal]=useState(false);const load=()=>api<{items:any[]}>('/api/v1/admin/custom-fields').then(v=>setItems(v.items)).catch(e=>props.notify(errorMessage(e),true));useEffect(()=>{void load()},[]);return <Frame {...props} title="Custom Field" subtitle="기업별 CRM 필드를 Schema ALTER 없이 Metadata + JSONB로 확장합니다." actions={<button className="btn btn-primary" onClick={()=>setModal(true)}>＋ Field 생성</button>}>{!items?<Spinner/>:<section className="panel table-panel">{items.length?<table><thead><tr><th>대상</th><th>Label · Key</th><th>Type</th><th>필수</th><th>순서</th><th>상태</th></tr></thead><tbody>{items.map(x=><tr key={x.id}><td><Status value={x.entityType}/></td><td><b>{x.label}</b><code className="table-sub">{x.key}</code></td><td>{x.type}</td><td>{x.required?'필수':'선택'}</td><td>{x.displayOrder}</td><td><Status value={x.active?'ACTIVE':'DISABLED'}/></td></tr>)}</tbody></table>:<Empty title="Custom Field가 없습니다" description="Customer, Contact, Lead, Opportunity, Quotation, Contract를 확장하세요."/>}</section>}{modal&&<FieldModal onClose={()=>setModal(false)} onSaved={()=>{setModal(false);load()}} notify={props.notify}/>}</Frame>}
function FieldModal({onClose,onSaved,notify}:{onClose:()=>void;onSaved:()=>void;notify:Props['notify']}){async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/admin/custom-fields',{method:'POST',body:JSON.stringify({entityType:f.get('entity'),key:f.get('key'),label:f.get('label'),type:f.get('type'),required:f.get('required')==='on',options:null,displayOrder:Number(f.get('order'))})});notify('Custom Field를 만들었습니다.');onSaved()}catch(e){notify(errorMessage(e),true)}}return <Modal title="Custom Field 생성" onClose={onClose}><form className="form" onSubmit={submit}><label>대상 Entity<select name="entity">{['Customer','Contact','Lead','Opportunity','Quotation','Contract'].map(x=><option key={x}>{x}</option>)}</select></label><label>Label *<input name="label" required/></label><label>Field Key *<input name="key" required pattern="[a-z0-9_]+" placeholder="purchase_cycle"/></label><label>Type<select name="type">{['Text','Textarea','Number','Money','Percent','Date','Datetime','Boolean','Select','Multi Select','User','Organization','URL'].map(x=><option key={x}>{x}</option>)}</select></label><label>표시 순서<input name="order" type="number" defaultValue="100"/></label><label className="check-label"><input name="required" type="checkbox"/> 필수 입력</label><div className="modal-actions"><button type="button" className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary">Field 생성</button></div></form></Modal>}

function Security(props:Props){const {items}=useSettings();const get=(ns:string,k:string,f:any)=>items?.find(x=>x.namespace===ns&&x.key===k)?.value??f;async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);try{await Promise.all([saveSetting({namespace:'auth',key:'local_login_enabled',value:f.get('local')==='on'}),saveSetting({namespace:'security',key:'session_minutes',value:Number(f.get('session'))}),saveSetting({namespace:'api',key:'rate_limit_per_minute',value:Number(f.get('rate'))}),saveSetting({namespace:'security',key:'export_enabled',value:f.get('export')==='on'}),saveSetting({namespace:'files',key:'max_upload_mb',value:Number(f.get('upload'))})]);props.notify('보안 정책을 저장했습니다.')}catch(e){props.notify(errorMessage(e),true)}}return <Frame {...props} title="보안 · 파일 · 알림" subtitle="Local Login, Session, API Rate Limit, Export와 파일 정책을 중앙 관리합니다.">{!items?<Spinner/>:<form className="settings-stack" onSubmit={submit}><section className="panel settings-section"><div className="settings-title"><span>◈</span><div><h2>인증 · Session · API</h2><p>Bootstrap Break Glass 로그인은 이 설정과 관계없이 항상 유지됩니다.</p></div></div><div className="form-grid"><label className="check-label"><input name="local" type="checkbox" defaultChecked={get('auth','local_login_enabled',true)}/> 일반 Local Login 허용</label><label>Session Timeout (분)<input name="session" type="number" min="15" defaultValue={get('security','session_minutes',480)}/></label><label>API Rate Limit / 분<input name="rate" type="number" min="0" defaultValue={get('api','rate_limit_per_minute',120)}/></label><label>최대 파일 크기 (MB)<input name="upload" type="number" min="1" defaultValue={get('files','max_upload_mb',20)}/></label><label className="check-label"><input name="export" type="checkbox" defaultChecked={get('security','export_enabled',true)}/> CSV / Excel Export 허용</label></div></section><section className="panel security-list">{[['Password','Argon2id · Raw Password 미저장'],['Browser','HttpOnly · SameSite · CSRF · CSP'],['SQL','Parameter Binding'],['Secret','AES-256-GCM Application Encryption'],['Personal Key','HMAC Digest · 1회 Secret 표시'],['MCP','Origin · Authentication · Tool Scope · Audit']].map(([k,v])=><div key={k}><span>✓</span><b>{k}</b><p>{v}</p></div>)}</section><div className="sticky-save"><span>주요 보안 변경은 Audit에 기록됩니다.</span><button className="btn btn-primary">보안 정책 저장</button></div></form>}</Frame>}

function Audit(props:Props){
  const [items,setItems]=useState<any[]|null>(null);const [selected,setSelected]=useState<any>(null);const [loading,setLoading]=useState(false);const [query,setQuery]=useState('');const [channel,setChannel]=useState('')
  const load=async(search=query,selectedChannel=channel)=>{setLoading(true);try{const params=new URLSearchParams({limit:'200'});if(search.trim())params.set('q',search.trim());if(selectedChannel)params.set('channel',selectedChannel);const value=await api<{items:any[]}>(`/api/v1/admin/audit?${params}`);setItems(value.items)}catch(e){props.notify(errorMessage(e),true)}finally{setLoading(false)}}
  useEffect(()=>{void load()},[])
  return <Frame {...props} title="Audit Log" subtitle="Web, API, MCP, Admin, Login과 Key 작업을 검색하고 변경 전후를 추적합니다." actions={<button className="btn btn-secondary" disabled={loading} onClick={()=>void load()}>{loading?'조회 중…':'↻ 새로고침'}</button>}>
    <form className="audit-filter panel" onSubmit={e=>{e.preventDefault();void load()}}><label className="filter-search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Actor, Action, Resource, Request ID 검색" aria-label="감사 로그 검색"/></label><select value={channel} onChange={e=>setChannel(e.target.value)} aria-label="채널 필터"><option value="">모든 Channel</option>{['WEB','API','MCP','ADMIN'].map(x=><option key={x}>{x}</option>)}</select><button className="btn btn-primary">필터 적용</button><button className="btn btn-ghost" type="button" onClick={()=>{setQuery('');setChannel('');void load('','')}}>초기화</button><span>{items?.length??0}건</span></form>
    {!items?<Spinner/>:items.length?<section className="panel table-panel"><table><thead><tr><th>시각</th><th>Actor</th><th>Channel</th><th>Action</th><th>Resource</th><th>IP · Request ID</th><th/></tr></thead><tbody>{items.map(x=><tr key={x.id}><td>{date(x.occurredAt)}</td><td><b>{x.actor||'SYSTEM'}</b></td><td><Status value={x.channel}/></td><td><code>{x.action}</code></td><td>{x.resource}<small className="table-sub">{x.resourceId}</small></td><td><code>{x.ip||'—'}</code><small className="table-sub truncate">{x.requestId}</small></td><td><button className="table-action" onClick={()=>setSelected(x)}>상세</button></td></tr>)}</tbody></table></section>:<section className="panel"><Empty icon="⌕" title="조건에 맞는 Audit이 없습니다" description="검색어나 Channel 필터를 바꿔 다시 조회하세요."/></section>}
    {selected&&<Modal title="Audit 상세" onClose={()=>setSelected(null)} wide><div className="audit-detail"><div className="audit-meta"><div><span>Actor</span><b>{selected.actor||'SYSTEM'}</b></div><div><span>Channel</span><Status value={selected.channel}/></div><div><span>Action</span><code>{selected.action}</code></div><div><span>Resource</span><b>{selected.resource} · {selected.resourceId||'—'}</b></div><div><span>IP</span><code>{selected.ip||'—'}</code></div><div><span>Request ID</span><code>{selected.requestId||'—'}</code></div></div><div className="audit-diff"><section><h3>변경 전</h3><pre>{JSON.stringify(selected.before??{},null,2)}</pre></section><section><h3>변경 후</h3><pre>{JSON.stringify(selected.after??{},null,2)}</pre></section></div></div></Modal>}
  </Frame>
}
function DataManagement(props:Props){return <Frame {...props} title="Import · Export" subtitle="Permission과 Data Scope가 적용되는 안전한 데이터 반입·반출입니다."><div className="import-grid"><section className="panel"><span className="import-icon">⇧</span><h2>CSV / Excel Import</h2><p>Column Mapping, Validation, Preview를 거쳐 데이터에 반영합니다.</p><div className="step-line"><span>파일 업로드</span><b>→</b><span>Mapping</span><b>→</b><span>검증</span><b>→</b><span>Import</span></div><button className="btn btn-primary">Import 시작</button></section><section className="panel"><span className="import-icon">⇩</span><h2>CSV / Excel Export</h2><p>현재 사용자의 Permission과 Data Scope로 필터링하고 Audit을 남깁니다.</p><div className="alert"><b>Export 정책 적용</b><span>관리자 정책과 사용자 데이터 범위를 넘는 데이터는 내보낼 수 없습니다.</span></div><button className="btn btn-secondary">Export 작업 보기</button></section></div></Frame>}

const formatBytes=(n:number)=>n>1e9?`${(n/1e9).toFixed(1)} GB`:n>1e6?`${(n/1e6).toFixed(1)} MB`:`${number(n)} B`
const relativeAdmin=(v?:string)=>v?date(v):'로그인 없음'
